// -----------------------------------------------
// Fabricated Items — editable; every change re-syncs Duct Items
// -----------------------------------------------
frappe.ui.form.on('Material Summary', {
    parent_finished_good: async function(frm, cdt, cdn) {
        const row = locals[cdt][cdn];
        // Always fetch fresh Sales Order / Fabrication List data for the picked item
        const ctx = await get_fabrication_context(frm, true);

        if (row.parent_finished_good) {
            const duplicate = (frm.doc.material_summary || []).some(r =>
                r.name !== row.name && r.parent_finished_good === row.parent_finished_good
            );
            if (duplicate) {
                frappe.msgprint(__('Fabricated Item {0} is already added.', [row.parent_finished_good]));
                frappe.model.set_value(cdt, cdn, 'parent_finished_good', '');
                return;
            }

            fill_fabricated_item(row, ctx);

            // Rebuild this item's Duct Items from fresh data
            (frm.doc.costing_sheet_item || []).slice().forEach(d => {
                if (d.parent_finished_goods_item === row.parent_finished_good) {
                    frappe.model.clear_doc(d.doctype, d.name);
                }
            });

            const in_fl = ctx.fl_materials.some(m => m.parent_finished_good === row.parent_finished_good);
            const in_so = ctx.so_items.some(s => s.parent_item === row.parent_finished_good);
            if (!in_fl && !in_so) {
                frappe.show_alert({
                    message: __('{0} not found in Fabrication List or Sales Order', [row.parent_finished_good]),
                    indicator: 'orange'
                });
            }
        } else {
            // No fabricated item on this row — drop its filled values from the totals
            Object.assign(row, {
                material_item_code: '', material_item_brand: '', material_item_uom: '',
                fl_item_gauge: 0, fl_item_specification: '', rate: 0, amount: 0,
                sum_of_fl_item_qty: 0, material_item_qty: 0,
                sum_of_duct_weight: 0, sum_of_duct_area_with_seam: 0
            });
        }

        frm.refresh_field('material_summary');
        sync_duct_items(frm, ctx);
        calculate_material_total(frm);
    },
    material_item_code: async function(frm) {
        sync_duct_items(frm, await get_fabrication_context(frm));
    },
    material_item_qty: function(frm, cdt, cdn) {
        set_fabricated_item_amount(cdt, cdn);
    },
    rate: function(frm, cdt, cdn) {
        set_fabricated_item_amount(cdt, cdn);
    },
    amount: function(frm, cdt, cdn) {
        calculate_material_total(frm);
    },
    material_summary_remove: async function(frm) {
        sync_duct_items(frm, await get_fabrication_context(frm));
        calculate_material_total(frm);
    }
});

function set_fabricated_item_amount(cdt, cdn) {
    const row = locals[cdt][cdn];
    frappe.model.set_value(cdt, cdn, 'amount', flt(row.rate) * flt(row.material_item_qty));
}

function calculate_material_total(frm) {
    let total = 0;
    (frm.doc.material_summary || []).forEach(row => {
        total += flt(row.amount);
    });
    frm.set_value('custom_material_total', flt(total, 2));
    frm.set_value('total_quotation_cost', flt(total, 2));
}

function unlock_fabricated_items(frm) {
    frm.set_df_property('material_summary', 'read_only', 0);

    const grid = frm.fields_dict.material_summary.grid;
    [
        'parent_finished_good', 'material_item_code', 'material_item_brand', 'rate',
        'material_item_uom', 'material_item_qty', 'sum_of_fl_item_qty', 'amount',
        'fl_item_gauge', 'fl_item_specification', 'sum_of_duct_weight', 'sum_of_duct_area_with_seam'
    ].forEach(fieldname => grid.update_docfield_property(fieldname, 'read_only', 0));
}

// -----------------------------------------------
// Fabrication List + Sales Order data, cached per form
// -----------------------------------------------
async function get_fabrication_context(frm, force) {
    const key = (frm.doc.fabrication_list || '') + '|' + (frm.doc.sod || '');
    if (!force && frm._fabrication_context && frm._fabrication_context.key === key) {
        return frm._fabrication_context;
    }

    const fl_doc = frm.doc.fabrication_list
        ? await frappe.db.get_doc('Fabrication List', frm.doc.fabrication_list)
        : null;

    const sales_order = (fl_doc && fl_doc.sales_order) || frm.doc.sod;
    const so_doc = sales_order ? await frappe.db.get_doc('Sales Order', sales_order) : null;

    frm._fabrication_context = {
        key: key,
        fl_materials: fl_doc ? (fl_doc.material_summary || []) : [],
        fl_acc_items: fl_doc ? (fl_doc.acc_item || []) : [],
        so_items: so_doc ? (so_doc.custom_parent_item || []) : []
    };
    return frm._fabrication_context;
}

// -----------------------------------------------
// Load all tables from the selected Fabrication List
// -----------------------------------------------
async function load_fabrication_list_items(frm) {
    frm.clear_table('accessory_item');
    frm.clear_table('material_summary');
    frm.clear_table('costing_sheet_item');

    frm.refresh_field('accessory_item');
    frm.refresh_field('material_summary');
    frm.refresh_field('costing_sheet_item');

    if (!frm.doc.fabrication_list) {
        calculate_total_amount(frm);
        calculate_material_total(frm);
        return;
    }

    const ctx = await get_fabrication_context(frm, true);

    // One Fabricated Item per parent FG — Sales Order values are per parent FG
    const parents = [...new Set(ctx.fl_materials.map(m => m.parent_finished_good).filter(Boolean))];
    parents.forEach(parent => {
        const row = frm.add_child('material_summary', { parent_finished_good: parent });
        fill_fabricated_item(row, ctx);
    });

    ctx.fl_acc_items.forEach(row => {
        const so_item = find_sales_order_item(ctx.so_items, row.parent_finished_good);

        const rate   = so_item ? flt(so_item.rate) : 0;
        const qty    = flt(row.qty);
        const amount = qty * rate;

        frm.add_child('accessory_item', {
            item_code:  row.item_code,
            item_name:  row.item_name,
            uom:        row.uom,
            quantity:   qty,
            rate:       rate,
            amount:     amount
        });
    });

    frm.refresh_field('material_summary');
    frm.refresh_field('accessory_item');

    sync_duct_items(frm, ctx);
    calculate_material_total(frm);
}

// Re-apply Sales Order / Fabrication List values on the existing Fabricated Items
// and rebuild their Duct Items. Accessory, Fabrication and other tables are kept.
async function refresh_from_sales_order(frm) {
    const ctx = await get_fabrication_context(frm, true);

    (frm.doc.material_summary || []).forEach(row => {
        if (row.parent_finished_good) fill_fabricated_item(row, ctx);
    });

    (frm.doc.costing_sheet_item || []).slice().forEach(d => {
        if (d.parent_finished_goods_item) frappe.model.clear_doc(d.doctype, d.name);
    });

    frm.refresh_field('material_summary');
    sync_duct_items(frm, ctx);
    calculate_material_total(frm);
    frm.dirty();
}

// Fabricated Item values come from the Sales Order parent item:
//   Sum of FL Item Qty = SO Quantity
//   Material Item Qty  = SO Total SPL Area SQM
//   Sum of Duct Weight = SO Total KG
// Falls back to Fabrication List totals when the item is not on the Sales Order.
function fill_fabricated_item(row, ctx) {
    const coils   = ctx.fl_materials.filter(m => m.parent_finished_good === row.parent_finished_good);
    const so_item = find_sales_order_item(ctx.so_items, row.parent_finished_good);
    const first   = coils[0] || {};
    const fl_sum  = fieldname => coils.reduce((total, c) => total + flt(c[fieldname]), 0);

    row.material_item_code         = coils.map(c => c.material_item_code).join(', ');
    row.material_item_brand        = first.material_item_brand;
    row.fl_item_gauge              = first.fl_item_gauge;
    row.fl_item_specification      = first.fl_item_specification;
    row.sum_of_duct_area_with_seam = fl_sum('sum_of_duct_area_with_seam');

    if (so_item) {
        row.material_item_uom  = so_item.fg_item_uom;
        row.rate               = flt(so_item.rate);
        row.sum_of_fl_item_qty = flt(so_item.quantity);
        row.material_item_qty  = flt(so_item.spl_area_sqm);
        row.sum_of_duct_weight = flt(so_item.total_kg);
    } else {
        row.material_item_uom  = first.material_item_uom;
        row.rate               = 0;
        row.sum_of_fl_item_qty = fl_sum('sum_of_fl_item_qty');
        row.material_item_qty  = fl_sum('sum_of_duct_area_with_seam');
        row.sum_of_duct_weight = fl_sum('sum_of_duct_weight');
    }

    row.amount = flt(row.rate) * flt(row.material_item_qty);
}

// -----------------------------------------------
// Duct Items = coil materials of the Fabricated Items.
// Rows of removed Fabricated Items are dropped, missing coils are added,
// existing rows (and manual edits on them) are kept. Rows added by hand
// without a parent FG are never touched. Per Unit Cost is set on save.
// -----------------------------------------------
function sync_duct_items(frm, ctx) {
    const wanted = [];
    (frm.doc.material_summary || []).forEach(fab => {
        if (!fab.parent_finished_good) return;

        let coils = ctx.fl_materials.filter(m => m.parent_finished_good === fab.parent_finished_good);
        if (!coils.length && fab.material_item_code) {
            coils = fab.material_item_code.split(',')
                .map(code => code.trim())
                .filter(Boolean)
                .map(code => ({ material_item_code: code, parent_finished_good: fab.parent_finished_good }));
        }
        coils.forEach(c => wanted.push(c));
    });

    const duct_key = (parent, item_code) => parent + '||' + item_code;
    const wanted_keys = new Set(wanted.map(c => duct_key(c.parent_finished_good, c.material_item_code)));

    (frm.doc.costing_sheet_item || []).slice().forEach(d => {
        if (d.parent_finished_goods_item && !wanted_keys.has(duct_key(d.parent_finished_goods_item, d.item_code))) {
            frappe.model.clear_doc(d.doctype, d.name);
        }
    });

    const existing_keys = new Set((frm.doc.costing_sheet_item || []).map(d =>
        duct_key(d.parent_finished_goods_item, d.item_code)
    ));

    wanted.forEach(c => {
        if (existing_keys.has(duct_key(c.parent_finished_good, c.material_item_code))) return;

        frm.add_child('costing_sheet_item', {
            item_code:                  c.material_item_code,
            item_name:                  c.material_item_code,
            parent_finished_goods_item: c.parent_finished_good,
            finished_goods_item:        null,
            uom:                        c.material_item_uom,
            quantity:                   flt(c.material_item_qty),
            rate:                       0,
            amount:                     0,
            selling_amount:             0,
            saving:                     0,
            item_brand:                 c.material_item_brand,
            item_guage:                 c.fl_item_gauge
        });
    });

    frm.refresh_field('costing_sheet_item');
    calculate_total_amount(frm);
}

function find_sales_order_item(sales_order_items, item_code) {
    if (!sales_order_items || !sales_order_items.length) return null;
    return sales_order_items.find(item => item.parent_item === item_code) || null;
}
